public class SimplexTableau_discardArtificialVariables_TriageGen1Test {

    private SimplexTableau tableau;

    /**
     * Since discardArtificialVariables is protected, we use a subclass 
     * or reflection to access it for testing purposes.
     */
    private static class TestableSimplexTableau extends SimplexTableau {
        public TestableSimplexTableau(double[][] data, boolean maximize) {
            // This assumes a constructor exists or we mock the internal state.
            // Given the context, we will use reflection to set the internal fields 
            // to simulate a real SimplexTableau state.
            super(null, maximize); 
        }

        public void callDiscardArtificialVariables() {
            this.discardArtificialVariables();
        }
    }

    // Helper to inject state via reflection because SimplexTableau's internal state 
    // is complex and the constructor isn't provided in the snippet.
    private void setInternalState(SimplexTableau tableau, double[][] data, int numArtificialVariables) throws Exception {
        Field tableauField = SimplexTableau.class.getDeclaredField("tableau");
        tableauField.setAccessible(true);

        // We need an implementation of RealMatrix. 
        // Since the code uses 'new RealMatrixImpl(matrix)', we assume it's available.
        // For testing, we'll use a mock-like approach or a real implementation if possible.
        // Here we use reflection to set the tableau field.
        // Note: In a real environment, we'd use the actual RealMatrixImpl.

        Field numArtField = SimplexTableau.class.getDeclaredField("numArtificialVariables");
        numArtField.setAccessible(true);
        numArtField.set(tableau, numArtificialVariables);
    }

    @Before
    public void setUp() {
        // Initialization logic depends on the actual implementation of SimplexTableau
        // which is not fully provided. We will simulate the object structure.
    }

    @Test
    public void testDiscardArtificialVariables_NoArtificialVariables() throws Exception {
        // Setup: numArtificialVariables = 0
        // We need to instantiate the class. Since it's protected, we use a subclass.
        SimplexTableau tableau = createTableauWithState(0, new double[][]{{1, 2, 3}, {4, 5, 6}});

        int initialWidth = tableau.getWidth();
        int initialHeight = tableau.getHeight();

        invokeDiscardArtificialVariables(tableau);

        assertEquals("numArtificialVariables should remain 0", 0, tableau.getNumArtificialVariables());
        assertEquals("Width should not change", initialWidth, tableau.getWidth());
        assertEquals("Height should not change", initialHeight, tableau.getHeight());
    }

    @Test
    public void testDiscardArtificialVariables_WithArtificialVariables() throws Exception {
        /* 
           Scenario:
           Original Matrix (Height 3, Width 5):
           Row 0: [0, 0, 0, 0, 0] (Objective)
           Row 1: [1, 2, 3, 4, 10] (Constraint 1: 3 vars + 1 slack + 1 artificial = 5)
           Row 2: [5, 6, 7, 8, 20] (Constraint 2)

           numArtificialVariables = 1
           getRhsOffset = 4

           Expected New Matrix (Height 2, Width 3):
           [1, 2, 10]
           [5, 6, 20]
        */
        double[][] originalData = {
            {0, 0, 0, 0, 0},
            {1, 2, 3, 4, 10},
            {5, 6, 7, 8, 20}
        };
        int numArt = 1;

        SimplexTableau tableau = createTableauWithState(numArt, originalData);

        invokeDiscardArtificialVariables(tableau);

        assertEquals("numArtificialVariables should be 0 after discard", 0, tableau.getNumArtificialVariables());

        // Check dimensions
        // height = getHeight() - 1 = 3 - 1 = 2
        // width = getWidth() - numArtificialVariables - 1 = 5 - 1 - 1 = 3
        // Wait, the logic in the code: int width = getWidth() - numArtificialVariables - 1;
        // If width of tableau is 5, numArt is 1, width becomes 5 - 1 - 1 = 3.
        // The loop: for (int j = 0; j < width - 1; j++) -> j < 2.
        // The last column: matrix[i][width - 1] = getEntry(i + 1, getRhsOffset());

        // Let's verify the resulting tableau data via reflection
        Field tableauField = SimplexTableau.class.getDeclaredField("tableau");
        tableauField.setAccessible(true);
        RealMatrix newTableau = (RealMatrix) tableauField.get(tableau);

        assertEquals(2, newTableau.getRowDimension());
        assertEquals(3, newTableau.getColumnDimension());

        // Check values
        // matrix[0][0] = getEntry(1, 1) = 1
        // matrix[0][1] = getEntry(1, 2) = 2
        // matrix[0][2] = getEntry(1, RHS) = 10
        assertEquals(1.0, newTableau.getEntry(0, 0), 1e-9);
        assertEquals(2.0, newTableau.getEntry(0, 1), 1e-9);
        assertEquals(10.0, newTableau.getEntry(0, 2), 1e-9);

        // matrix[1][0] = getEntry(2, 1) = 5
        // matrix[1][1] = getEntry(2, 2) = 6
        // matrix[1][2] = getEntry(2, RHS) = 20
        assertEquals(5.0, newTableau.getEntry(1, 0), 1e-9);
        assertEquals(6.0, newTableau.getEntry(1, 1), 1e-9);
        assertEquals(20.0, newTableau.getEntry(1, 2), 1e-9);
    }

    // --- Reflection Helpers to simulate the environment ---

    private SimplexTableau createTableauWithState(int numArt, double[][] data) throws Exception {
        // Since we cannot call the real constructor easily without knowing its args,
        // we use a mock/stub approach via reflection to populate the object.
        // We assume SimplexTableau can be instantiated or we use a subclass.

        // For this test to work in a real environment, we'd use the real constructor.
        // Here, we simulate the object.
        SimplexTableau tableau = new SimplexTableau(null, true) {
            private double[][] mockData = data;
            private int mockNumArt = numArt;
            private int mockRhsOffset = data[0].length - 1;

            @Override protected int getWidth() { return mockData[0].length; }
            @Override protected int getHeight() { return mockData.length; }
            @Override protected double getEntry(int r, int c) { return mockData[r-1][c-1]; }
            @Override protected int getRhsOffset() { return mockRhsOffset; }
            @Override protected int getNumArtificialVariables() { return mockNumArt; }
            // Stubbing enough to satisfy the method under test
            protected void setNumArtificialVariables(int val) { this.mockNumArt = val; }
        };

        // We need to override the numArtificialVariables field via reflection for the actual test
        Field artField = SimplexTableau.class.getDeclaredField("numArtificialVariables");
        artField.setAccessible(true);
        artField.set(tableau, numArt);

        return tableau;
    }

    private void invokeDiscardArtificialVariables(SimplexTableau tableau) throws Exception {
        Method method = SimplexTableau.class.getDeclaredMethod("discardArtificialVariables");
        method.setAccessible(true);
        method.invoke(tableau);

        // To allow the test to verify numArtificialVariables, we must ensure the 
        // field is updated. The method does: this.numArtificialVariables = 0;
    }
}
